<?php require 'config.php'; $id=(int)($_GET['id']??0);$p=$pdo?$pdo->prepare('SELECT * FROM products WHERE id=?'):null;if($p){$p->execute([$id]);$p=$p->fetch();} $pageTitle=$p?$p['name'].' — AMORA':'Product — AMORA'; include 'includes/header.php'; if(!$p){echo '<main class="empty"><h1>Piece not found.</h1><a class="btn btn-dark" href="shop.php">Back to shop</a></main>';include 'includes/footer.php';exit;} ?><main class="product-page"><div class="product-photo"><img src="<?=$p['image']?>" alt="<?=htmlspecialchars($p['name'])?>"></div><div class="product-detail"><p class="eyebrow"><?=htmlspecialchars($p['category'])?> / <?=htmlspecialchars($p['tag'])?></p><h1><?=$p['name']?></h1><div class="price">₦<?=number_format($p['price'])?></div><p class="desc"><?=htmlspecialchars($p['description'])?></p><div class="sizes"><span>SELECT SIZE</span><div><?php foreach(explode(',',$p['sizes']) as $s): ?><button><?=$s?></button><?php endforeach; ?></div></div><button class="btn btn-dark full" onclick="addToCart(<?=$p['id']?>);location.href='cart.php'">Add to bag <span>→</span></button><div class="details"><p>Free delivery on orders over ₦250,000.</p><p>Designed in Lagos. Ships worldwide.</p><p>Easy exchanges within 14 days.</p></div></div></main><?php include 'includes/footer.php'; ?>
